function attack(useSkill=false){if(!state)return;const now=performance.now();const skillCD=classes[state.className].cooldown*1000;if(useSkill&&now-lastAttack<skillCD)return;let target=nearestActor(a=>a.kind==='monster'&&a.alive,classes[state.className].range);if(!target){toast('No monsters in range. Explore the meadow.');return}if(useSkill&&state.mp<15){toast('Not enough MP.');return}if(useSkill){lastAttack=now;state.mp-=15;$('#skill-cooldown').style.display='block';setTimeout(()=>$('#skill-cooldown').style.display='none',classes[state.className].cooldown*1000)}const base=classes[state.className].attack+(state.level-1)*3;const crit=Math.random()<Math.min(.15+(state.className==='Assassin'?.1:0),.5);let amount=Math.round(base*(useSkill?2.2:1)*(crit?1.8:1));target.actor.hp-=amount;target.actor.flash=0.18;damageFloat(`${crit?'✦ CRIT! ':''}${amount}`);particles.push({x:target.actor.x,y:target.actor.y,life:.45,type:'hit'});if(target.actor.hp<=0){target.actor.alive=false;target.actor.respawn=Date.now()+10000;state.kills++;let gold=6+Math.floor(Math.random()*9);state.gold+=gold;state.materials['Slime Gel']=(state.materials['Slime Gel']||0)+1;awardXP(24);if(Math.random()<.35){let type=Math.random()<.7?'Sunleaf':'Iron Ore';state.materials[type]=(state.materials[type]||0)+1;if(type==='Sunleaf')advanceQuest('herbs');}if(Math.random()<.3)directDrop();advanceQuest('slimes');toast(`Monster defeated · +24 XP · ${gold} Gold`);save();}refreshHUD();}
function directDrop(){let roll=Math.random(),rarity=roll<.6?'Common':roll<.85?'Grey':roll<.95?'Green':'Blue';let item={name:`${['Meadow','Woven','Grove','Dawn'][Math.floor(Math.random()*4)]} ${slots[Math.floor(Math.random()*7)]}`,type:slots[Math.floor(Math.random()*7)],rarity,level:3,icon:['⚔','♢','✧','♧'][Math.floor(Math.random()*4)]};state.inventory.push(item);toast(`${rarity} T3 drop: ${item.name}`);save();}
function potion(){if(state.potions<1){toast('No potions. Visit a merchant.');return}const c=classes[state.className];if(state.hp>=c.hp&&state.mp>=c.mp){toast('Your health and mana are full.');return}state.potions--;state.hp=Math.min(c.hp,state.hp+Math.round(c.hp*.45));state.mp=Math.min(c.mp,state.mp+Math.round(c.mp*.3));refreshHUD();save();toast('Potion used · HP and MP restored.');}
function respawn(){const c=classes[state.className];state.hp=c.hp;state.mp=c.mp;state.position={x:510,y:465};camera={...state.position};toast('You were revived at Dawnshire.');refreshHUD();save();}

