 // path inlay
 ctx.beginPath();ctx.moveTo(-180,450);ctx.bezierCurveTo(180,340,270,560,500,482);ctx.bezierCurveTo(700,415,715,210,1060,248);ctx.bezierCurveTo(1240,270,1330,190,1500,125);ctx.strokeStyle='#d5c49e';ctx.lineWidth=2;ctx.setLineDash([6,14]);ctx.stroke();ctx.setLineDash([]);
