 // stones around town
 for(const [x,y] of [[349,464],[776,528],[535,386],[304,550],[812,400]]){ctx.fillStyle='#7c866f';ctx.beginPath();ctx.ellipse(x,y,7,4,.2,0,7);ctx.fill();ctx.fillStyle='#aeb49a';ctx.beginPath();ctx.ellipse(x-2,y-2,3,1,.2,0,7);ctx.fill()}
