 let near=nearestActor(a=>a.kind==='npc',110);let prompt=$('#interact-prompt');if(near){prompt.classList.remove('hidden');$('#interact-name').textContent=near.actor.name;prompt.style.left=`${Math.max(14,Math.min(w-100,(near.actor.x-camera.x)*s+w/2))}px`;prompt.style.top=`${Math.max(60,Math.min(h-80,(near.actor.y-camera.y)*s+h/2-48))}px`}else prompt.classList.add('hidden');
