function drawTree(x,y,scale,variant,distant){ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);ctx.fillStyle='#344b3b';ctx.beginPath();ctx.ellipse(7,11,22,12,0,0,7);ctx.fill();ctx.fillStyle=distant?'#506b4e':'#586f4a';ctx.beginPath();ctx.moveTo(-24,5);ctx.lineTo(-14,-26);ctx.lineTo(-6,-19);ctx.lineTo(3,-43);ctx.lineTo(13,-18);ctx.lineTo(23,5);ctx.closePath();ctx.fill();ctx.fillStyle=variant>.5?'#718357':'#657b50';ctx.beginPath();ctx.moveTo(-16,-1);ctx.lineTo(-8,-27);ctx.lineTo(0,-17);ctx.lineTo(7,-34);ctx.lineTo(17,-1);ctx.closePath();ctx.fill();ctx.fillStyle='#879265';ctx.globalAlpha=.65;ctx.beginPath();ctx.ellipse(-4,-23,5,3,-.4,0,7);ctx.fill();ctx.restore()}
function drawBuilding(x,y,w,h,wall,roof,label){ctx.save();ctx.fillStyle='#4e5b4b55';ctx.beginPath();ctx.ellipse(x+w/2,y+h+9,w*.65,13,0,0,7);ctx.fill();ctx.fillStyle='#4d5348';ctx.fillRect(x+5,y+h-7,w-10,13);ctx.fillStyle=wall;ctx.fillRect(x,y+15,w,h-17);ctx.fillStyle=roof;ctx.beginPath();ctx.moveTo(x-9,y+19);ctx.lineTo(x+w*.5,y-10);ctx.lineTo(x+w+9,y+19);ctx.closePath();ctx.fill();ctx.strokeStyle='#765b45';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#795b43';ctx.fillRect(x+w*.42,y+h-27,w*.18,20);ctx.fillStyle='#e7d7a9';ctx.fillRect(x+12,y+30,13,11);ctx.fillRect(x+w-25,y+30,13,11);ctx.fillStyle='#715d45';ctx.fillRect(x+w*.5-23,y+7,46,12);ctx.fillStyle='#faf0d7';ctx.font='6px sans-serif';ctx.textAlign='center';ctx.fillText(label,x+w/2,y+15);ctx.restore()}
function drawPerson(x,y,color,scale=1){ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);ctx.fillStyle='#2e3b32';ctx.beginPath();ctx.ellipse(0,4,10,5,0,0,7);ctx.fill();ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(-8,-1);ctx.lineTo(-6,-20);ctx.lineTo(6,-20);ctx.lineTo(10,0);ctx.closePath();ctx.fill();ctx.fillStyle='#d8b48c';ctx.beginPath();ctx.arc(0,-25,7,0,7);ctx.fill();ctx.fillStyle='#5e493e';ctx.beginPath();ctx.arc(0,-28,7,Math.PI,0);ctx.fill();ctx.restore()}
function drawNPC(a){drawPerson(a.x,a.y,a.color,.9);ctx.fillStyle='#fff4c9';ctx.font='10px sans-serif';ctx.textAlign='center';ctx.fillText(a.mark,a.x,a.y-40);ctx.fillStyle='#fffdf1';ctx.font='8px sans-serif';ctx.shadowColor='#26342b';ctx.shadowBlur=4;ctx.fillText(a.name,a.x,a.y+15);ctx.shadowBlur=0}
function drawMonster(a,t){let bob=Math.sin(t/320+a.phase)*2;ctx.save();ctx.translate(a.x,a.y+bob);ctx.fillStyle='#314b3766';ctx.beginPath();ctx.ellipse(0,5,18,8,0,0,7);ctx.fill();if(a.type==='slime'){let grad=ctx.createRadialGradient(-5,-6,2,0,0,22);grad.addColorStop(0,'#c7e29b');grad.addColorStop(1,a.flash?'#fff': '#679766');ctx.fillStyle=grad;ctx.beginPath();ctx.ellipse(0,-4,18,15,0,Math.PI,Math.PI*2);ctx.lineTo(16,0);ctx.quadraticCurveTo(0,10,-16,0);ctx.closePath();ctx.fill();ctx.fillStyle='#243a32';ctx.beginPath();ctx.arc(-6,-2,1.7,0,7);ctx.arc(6,-2,1.7,0,7);ctx.fill();ctx.strokeStyle='#344d39';ctx.lineWidth=1;ctx.beginPath();ctx.arc(0,0,4,.2,2.9);ctx.stroke()}else{ctx.fillStyle=a.flash?'#fff':'#715e48';ctx.beginPath();ctx.ellipse(0,-5,18,12,0,0,7);ctx.fill();ctx.beginPath();ctx.moveTo(-11,-13);ctx.lineTo(-15,-27);ctx.lineTo(-4,-16);ctx.moveTo(11,-13);ctx.lineTo(15,-27);ctx.lineTo(4,-16);ctx.fill();ctx.fillStyle='#eddc9c';ctx.fillRect(-8,-7,4,2);ctx.fillRect(4,-7,4,2)}if(a.hp<a.maxHp){ctx.fillStyle='#38413a';ctx.fillRect(-15,-25,30,3);ctx.fillStyle='#d87960';ctx.fillRect(-15,-25,30*(a.hp/a.maxHp),3)}ctx.fillStyle='#fffdf0';ctx.font='7px sans-serif';ctx.textAlign='center';ctx.shadowColor='#17241a';ctx.shadowBlur=3;ctx.fillText(a.name,a.x,a.y-30);ctx.shadowBlur=0;ctx.restore()}
function drawPlayer(t){let x=state.position.x,y=state.position.y,bob=(Math.abs(movement.x)+Math.abs(movement.y)>.05)?Math.sin(t/75)*2:0;ctx.save();ctx.translate(x,y+bob);ctx.fillStyle='#1f2c2760';ctx.beginPath();ctx.ellipse(0,5,16,8,0,0,7);ctx.fill();ctx.scale(state.gender==='female'?.95:1,1);if(state.faction==='Angels'){ctx.fillStyle='#efe5c5';ctx.globalAlpha=.75;ctx.beginPath();ctx.moveTo(-8,-18);ctx.quadraticCurveTo(-40,-52,-20,-50);ctx.quadraticCurveTo(-7,-41,-3,-23);ctx.moveTo(8,-18);ctx.quadraticCurveTo(40,-52,20,-50);ctx.quadraticCurveTo(7,-41,3,-23);ctx.fill();ctx.globalAlpha=1}else{ctx.fillStyle='#7a463f';ctx.beginPath();ctx.moveTo(-7,-18);ctx.lineTo(-31,-41);ctx.lineTo(-16,-36);ctx.lineTo(-12,-47);ctx.lineTo(-2,-24);ctx.moveTo(7,-18);ctx.lineTo(31,-41);ctx.lineTo(16,-36);ctx.lineTo(12,-47);ctx.lineTo(2,-24);ctx.fill()}
 let outfit=state.outfit==='Sentinel'?'#847b63':state.outfit==='Runebound'?'#3e5e70':'#a88158';ctx.fillStyle=state.mounted?'#7b6950':outfit;ctx.beginPath();ctx.moveTo(-9,-25);ctx.lineTo(-12,-7);ctx.lineTo(-10,1);ctx.lineTo(9,1);ctx.lineTo(12,-7);ctx.lineTo(8,-25);ctx.closePath();ctx.fill();ctx.fillStyle='#d4ad88';ctx.beginPath();ctx.arc(0,-30,8,0,7);ctx.fill();ctx.fillStyle=state.hair;ctx.beginPath();ctx.arc(0,-32,8,Math.PI,Math.PI*2);ctx.lineTo(7,-29);ctx.lineTo(5,-26);ctx.lineTo(-6,-27);ctx.closePath();ctx.fill();ctx.fillStyle=state.eye==='Jade'?'#6a9c74':state.eye==='Amethyst'?'#9775a6':state.eye==='Azure'?'#6b9eb6':'#b69452';ctx.fillRect(-4,-30,2,1.6);ctx.fillRect(3,-30,2,1.6);if(state.className==='Warrior'){ctx.strokeStyle='#d8d1b4';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(11,-7);ctx.lineTo(22,-30);ctx.stroke();ctx.fillStyle='#c5a96c';ctx.fillRect(18,-30,8,2)}else if(state.className==='Mage'){ctx.strokeStyle='#9bc2c1';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(15,-6);ctx.lineTo(17,-40);ctx.stroke();ctx.fillStyle='#b9daf0';ctx.beginPath();ctx.arc(17,-42,4,0,7);ctx.fill()}else{ctx.fillStyle='#d7d0bc';ctx.beginPath();ctx.moveTo(9,-9);ctx.lineTo(19,-22);ctx.lineTo(16,-22);ctx.lineTo(7,-12);ctx.fill()}ctx.restore();ctx.fillStyle='#fffdf0';ctx.font='9px sans-serif';ctx.textAlign='center';ctx.shadowColor='#1c2a22';ctx.shadowBlur=4;ctx.fillText(state.name,x,y-54);ctx.shadowBlur=0;}
function gameLoop(t){const dt=Math.min(.04,(t-lastFrame)/1000||0);lastFrame=t;if(state&&$('#game').classList.contains('hidden')===false){if(movement.x||movement.y){const len=Math.hypot(movement.x,movement.y)||1;let speed=state.mounted?190:130;state.position.x=Math.max(80,Math.min(1450,state.position.x+movement.x/len*speed*dt));state.position.y=Math.max(100,Math.min(880,state.position.y+movement.y/len*speed*dt))}if(state.hp<classes[state.className].hp)state.hp=Math.min(classes[state.className].hp,state.hp+dt*.65);if(state.mp<classes[state.className].mp)state.mp=Math.min(classes[state.className].mp,state.mp+dt*.9);refreshHUD();drawWorld(t)}requestAnimationFrame(gameLoop)}

