function gameLoop(t){const dt=Math.min(.04,(t-lastFrame)/1000||0);lastFrame=t;if(state&&$('#game').classList.contains('hidden')===false){if(movement.x||movement.y){const len=Math.hypot(movement.x,movement.y)||1;let speed=state.mounted?190:130;state.position.x=Math.max(80,Math.min(1450,state.position.x+movement.x/len*speed*dt));state.position.y=Math.max(100,Math.min(880,state.position.y+movement.y/len*speed*dt))}if(state.hp<classes[state.className].hp)state.hp=Math.min(classes[state.className].hp,state.hp+dt*.65);if(state.mp<classes[state.className].mp)state.mp=Math.min(classes[state.className].mp,state.mp+dt*.9);refreshHUD();drawWorld(t)}requestAnimationFrame(gameLoop)}
function openModal(title,kicker,body,wide=false){const root=$('#modal-root');root.innerHTML=`<div class="modal-backdrop"><section class="game-modal ${wide?'wide':''}" role="dialog" aria-modal="true"><header class="modal-head"><div><span class="modal-kicker">${kicker}</span><h2>${title}</h2></div><button class="modal-close" aria-label="Close">×</button></header><div class="modal-body">${body}</div></section></div>`;root.querySelector('.modal-close').onclick=closeModal;root.querySelector('.modal-backdrop').addEventListener('pointerdown',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()});root.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>panelAction(b.dataset.action,b.dataset.value)));}
function closeModal(){$('#modal-root').innerHTML='';selectedItem=null}
function itemGrid(items,clickable=true){return `<div class="item-grid">${Array.from({length:24},(_,i)=>{let item=items[i];return item?`<button class="item-card" data-action="select-item" data-value="${i}"><span class="item-icon">${item.icon||'✧'}</span><b class="rarity ${item.rarity?.toLowerCase()||''}">${item.name}</b><small>${item.rarity||'Common'}${item.level?` · T${item.level}`:''}${item.qty?` · ×${item.qty}`:''}</small></button>`:`<div class="item-card empty-slot"><span class="item-icon">·</span><small>Empty</small></div>`}).join('')}</div>`}
function panel(name){if(!state)return;switch(name){case'bag':openInventory();break;case'equipment':openEquipment();break;case'quests':openQuests();break;case'world':openWorld();break;case'craft':openCraft();break;case'market':openMarket();break;case'shop':openShop();break;case'profile':openProfile();break;case'dungeon':openDungeon();break}}
function openInventory(){let body=`<div class="modal-tabs"><button class="selected">All items</button><button>Materials</button><button>Quest items</button></div><div class="inventory-layout"><div>${itemGrid(state.inventory)}<div class="item-detail" id="item-detail"><div><b>Choose an item</b><p>Select an item to inspect, equip, or use it.</p></div></div></div><aside class="inventory-side"><h3>Pack · ${state.inventory.length}/36</h3><p>◈ ${state.gold} Gold</p><p>◆ ${state.gems} Gems</p><p>🧪 ${state.potions} Potions</p><p>⛏ Slime Gel · ${state.materials['Slime Gel']||0}</p><p>☘ Sunleaf · ${state.materials.Sunleaf||0}</p><p>◈ Iron Ore · ${state.materials['Iron Ore']||0}</p></aside></div>`;openModal('Inventory','YOUR BELONGINGS',body,true)}
function openEquipment(){let body=`<p>Nine places to make your own. Equipment stats are local to this adventure.</p><div class="equipment-grid">${slots.map((s,i)=>`<div class="equip-slot"><span class="slot-icon">${['♧','♢','♧','◈','♧','⌁','⚔','◉','✧'][i]}</span><small>${s}</small><b>${state.equipment[s]||'Empty slot'}</b></div>`).join('')}</div><div class="equip-total"><span>Attack <b>${classes[state.className].attack+(state.level-1)*3}</b></span><span>Critical <b>${Math.min(50,10+(state.className==='Assassin'?10:0))}%</b></span><span>Class <b>${state.className}</b></span></div>`;openModal('Equipment','ARMOR & ARMS',body)}
function openQuests(){let body=`<div class="quest-list">${state.quests.map(q=>`<div class="quest-card ${q.done?'done':''}"><span>${q.done?'✓':'✧'}</span><div><b>${q.title}</b><p>${q.desc}</p><small>${q.done?'COMPLETED':`${q.progress}/${q.target} · ${q.reward}`}</small></div>${!q.done&&!q.active?`<button class="small-btn" data-action="accept-quest" data-value="${q.id}">Accept</button>`:''}</div>`).join('')}<div class="quest-card"><span>⌖</span><div><b>Daily fieldwork</b><p>Defeat monsters and gather materials for the village.</p><small>EVERGREEN · 0/5 · 30 Gold</small></div></div></div>`;openModal('Quest journal','YOUR CALLING',body)}
function openWorld(){let body=`<p>Eight distinct realms wait beyond the Greendale border. Explore at your own pace; the paths open as your story grows.</p><div class="world-map">${regions.map((r,i)=>`<button class="region-card ${state.unlockedRegions.includes(i)?'':'locked'} ${state.region===i?'current':''}" data-action="travel-region" data-value="${i}" ${state.unlockedRegions.includes(i)?'':'disabled'}><span class="region-mark">${['❋','♜','♣','☽','❄','☼','♨','✧'][i]}</span><b>${r}</b><small>${state.unlockedRegions.includes(i)?(state.region===i?'YOU ARE HERE':'DISCOVERED'):`REQUIRES LEVEL ${[0,3,5,7,9,11,14,18][i]}`}</small></button>`).join('')}</div><div class="town-pills">${towns.map(t=>`<span>⌂ ${t}</span>`).join('')}</div><div class="action-bar"><small>Teleportation fare · ${state.settings.teleport} Gold</small></div>`;openModal('The known world','AETHERIA · REALM MAP',body,true)}
function openCraft(){let selected=state.inventory.find(i=>i===selectedItem);let body=`<div class="modal-tabs"><button class="selected" data-action="craft-tab" data-value="fusion">Fusion</button><button data-action="craft-tab" data-value="forge">Blacksmith</button><button data-action="craft-tab" data-value="gather">Gather</button></div><div class="craft-layout"><article class="recipe-card"><h3>Item fusion</h3><p>Combine four identical items to advance their tier. Nothing is destroyed at random.</p><div class="recipe-line"><span>T3 → T2 → T1</span><b>4 identical items</b></div><div class="recipe-line"><span>T1 → next rarity T3</span><b>4 identical items</b></div><div class="recipe-line"><span>Fusion fee</span><b class="price">${state.settings.fusion} Gold</b></div><div class="action-bar"><button class="primary-small" data-action="fuse">Fuse selected</button><small>${selected?selected.name:'Choose an item from your bag first'}</small></div></article><article class="recipe-card"><h3>Legendary forge</h3><p>Legendary gear is crafted at a blacksmith. Purple and higher gear never drops directly.</p><div class="recipe-line"><span>Rare gear recipe</span><b>1 recipe</b></div><div class="recipe-line"><span>Ember Shard</span><b>${state.materials['Ember Shard']||0}/8</b></div><div class="recipe-line"><span>Boss Stone</span><b>${state.materials['Boss Stone']||0}/1</b></div><div class="recipe-line"><span>Forge fee</span><b class="price">${state.settings.craft} Gold</b></div><div class="action-bar"><button class="primary-small" data-action="forge">Forge Legendary</button><small>Recipe drops from region bosses</small></div></article><article class="recipe-card"><h3>Higher ascension</h3><p>Four of one rarity create a single item of the next rarity. Mythic and Divine are fusion-only.</p><div class="recipe-line"><span>Legendary ×4</span><b>→ Mythic</b></div><div class="recipe-line"><span>Mythic ×4</span><b>→ Divine</b></div><div class="recipe-line"><span>Drop rule</span><b>Never direct drops</b></div></article><article class="recipe-card"><h3>Materials & recipes</h3><p>Gather in the world or earn rare materials from bosses.</p><div class="recipe-line"><span>Sunleaf · Slime Gel · Iron Ore</span><b>${state.materials.Sunleaf||0} · ${state.materials['Slime Gel']||0} · ${state.materials['Iron Ore']||0}</b></div><div class="recipe-line"><span>Critical chance cap</span><b>50%</b></div></article></div>`;openModal('The village forge','CRAFTING & FUSION',body,true)}
function openMarket(){let body=`<p>Local demo listings are stored only in this browser. No real players or online marketplace are connected.</p><div class="action-bar"><input id="listing-name" class="name-input" style="margin:0;flex:1" placeholder="Item name to list" /><button class="primary-small" data-action="list-item">List for 25 Gold</button></div><table class="market-table"><thead><tr><th>ITEM</th><th>SELLER</th><th>PRICE</th><th></th></tr></thead><tbody>${(state.localListings.length?state.localListings:[{name:'Groveweave Gloves',seller:'Local listing',price:68},{name:'Sunleaf Bundle ×4',seller:'Local listing',price:24},{name:'Iron Ore ×2',seller:'Local listing',price:52}]).map((a,i)=>`<tr><td>◇ ${a.name}</td><td>${a.seller}</td><td>◈ ${a.price}</td><td><button class="small-btn" data-action="buy-listing" data-value="${i}">Buy</button></td></tr>`).join('')}</tbody></table>`;openModal('Realm exchange','PLAYER MARKETPLACE · LOCAL',body)}
function openShop(){let products=[['Costume · Moonlit','A silver-threaded travel cloak','◉',95,'Gems'],['Hair · Starfall','A soft celestial braid','✧',60,'Gems'],['Mount · Dawnstag','A gentle golden trailblazer','♘',140,'Gems'],['Pet · Wisp','A little wandering light','☼',75,'Gems'],['Weapon effect · Ember','A warm ember blade trail','⚔',80,'Gems'],['Faction wings','Cosmetic wings · quest or shop only','羽',180,'Gems'],['Gem pouch','Earn Gems in play, or choose more','◆',0,'Gold']];let body=`<p>Everything here is optional and cosmetic. Gems can also be earned through quests and play. No required purchases.</p><div class="merchant-grid">${products.map((p,i)=>`<article class="product-card"><span>${p[2]}</span><b>${p[0]}</b><small>${p[1]}</small><button class="small-btn" data-action="buy-cosmetic" data-value="${i}">${p[3]===0?'Free · claim':`◆ ${p[3]} Gems`}</button></article>`).join('')}</div><div class="action-bar"><small>Optional membership · convenience cosmetics only</small><button class="small-btn" data-action="membership">Preview membership</button></div>`;openModal('Sanctum of wonders','OPTIONAL · FREE-TO-PLAY',body,true)}
function openProfile(){let body=`<div class="npc-byline"><span>✦</span><div><b>${state.name}</b><small>Level ${state.level} ${state.className} · ${state.faction}</small></div></div><div class="equip-total"><span>Adventures <b>${state.kills}</b></span><span>Quests <b>${state.completedQuests}</b></span><span>Skill rank <b>${state.skillLevel}/10</b></span></div><p>Character progress saves on this device. This is a local single-player adventure, not an online account or persistent multiplayer server.</p><div class="action-bar"><button class="small-btn" data-action="reset-save">Return to character creation</button><small>Last saved ${new Date(state.savedAt||Date.now()).toLocaleTimeString()}</small></div>`;openModal('Adventurer profile','YOUR CHARACTER',body)}
function openDungeon(){let body=`<p>Follow the trail into a solo trial. Dungeon encounters and boss rewards are simulated locally.</p><div class="quest-card"><span>♜</span><div><b>Roots of the Old Grove</b><p>Clear the hollow and face the Briar Guardian. Recommended level 3.</p><small>REWARD · XP · GOLD · BOSS STONE CHANCE</small></div><button class="primary-small" data-action="enter-dungeon">Enter</button></div><div class="quest-card"><span>♨</span><div><b>Ashen Gate</b><p>A sealed challenge deep in the Dominion. Recommended level 14.</p><small>LOCKED · REQUIRES LEVEL 14</small></div></div>`;openModal('Dungeon gate','INSTANCED CHALLENGES',body)}

