function talkTo(name){switch(name){case'Mira':openQuests();if(!state.quests.some(q=>q.active&&!q.done)){let q=state.quests.find(q=>!q.done);if(q){q.active=true;toast(`New quest: ${q.title}`);refreshHUD();save()}}break;case'Bram':openCraft();break;case'Elowen':openShop();break;case'Tomas':openInventory();break;case'Lysa':openWorld();break;default:toast(`${name} has nothing to say.`)}}
function panelAction(action,value){if(!state)return;const idx=Number(value);switch(action){
 case'select-item':showItemDetail(state.inventory[idx]);break;
 case'equip-item':if(!selectedItem||!slots.includes(selectedItem.type)){toast('This item cannot be equipped.');break}state.equipment[selectedItem.type]=selectedItem.name;selectedItem.equipped=true;toast(`${selectedItem.name} equipped.`);save();openEquipment();break;
 case'use-item':if(!selectedItem)break;if(/potion/i.test(selectedItem.name)||selectedItem.type==='Consumable'){if(state.potions<1){toast('No potions remain.');break}state.potions--;selectedItem.qty=Math.max(0,(selectedItem.qty||1)-1);if(selectedItem.qty===0)state.inventory.splice(state.inventory.indexOf(selectedItem),1);let c=classes[state.className];state.hp=Math.min(c.hp,state.hp+Math.round(c.hp*.45));state.mp=Math.min(c.mp,state.mp+Math.round(c.mp*.3));refreshHUD();save();toast('Potion used · HP and MP restored.');selectedItem=null;openInventory()}else toast('That item cannot be used right now.');break;
 case'discard-item':if(Number.isInteger(idx)&&state.inventory[idx]){let item=state.inventory.splice(idx,1)[0];toast(`${item.name} discarded.`);save();selectedItem=null;openInventory()}break;
 case'accept-quest':{let q=state.quests.find(q=>q.id===value&&!q.done);if(q){state.quests.forEach(a=>a.active=false);q.active=true;toast(`Quest accepted: ${q.title}`);save();refreshHUD();openQuests()}}break;
 case'travel-region':{let region=Number(value),req=[0,3,5,7,9,11,14,18][region];if(!Number.isInteger(region)||!regions[region])break;if(state.level<req){toast(`Reach level ${req} to travel there.`);break}if(state.gold<state.settings.teleport){toast('Not enough Gold for the journey.');break}state.gold-=state.settings.teleport;state.region=region;state.currentTown=null;state.position={x:510,y:465};camera={...state.position};if(!state.unlockedRegions.includes(region))state.unlockedRegions.push(region);save();refreshHUD();toast(`You journey to ${regions[region]}.`);openWorld()}break;
 case'craft-tab':modalTab=value;toast(`${value==='fusion'?'Fusion':value==='forge'?'Blacksmith':'Gather'} selected.`);break;
 case'fuse':{if(!selectedItem){toast('Select an item from your bag first.');break}let matches=state.inventory.filter(i=>i.name===selectedItem.name&&i.type===selectedItem.type&&i.rarity===selectedItem.rarity&&i.level===selectedItem.level);if(matches.length<4){toast('Fusion requires four identical items.');break}if(state.gold<state.settings.fusion){toast('Not enough Gold for fusion.');break}state.gold-=state.settings.fusion;for(let i=0;i<4;i++)state.inventory.splice(state.inventory.indexOf(matches[i]),1);let tier=selectedItem.level||3;let rarity=selectedItem.rarity||'Common';if(tier>1)tier--;else{tier=3;let order=['Common','Grey','Green','Blue','Purple','Legendary','Mythic','Divine'];rarity=order[Math.min(order.length-1,order.indexOf(rarity)+1)]}state.inventory.push({...selectedItem,level:tier,rarity,equipped:false});selectedItem=null;save();toast(`Fusion complete · ${rarity} T${tier}`);openCraft()}break;
