 case'list-item':{let name=$('#listing-name')?.value.trim();if(!name){toast('Enter a listing name.');break}if(state.gold<25){toast('Not enough Gold to list an item.');break}state.gold-=25;state.localListings.push({name:name.slice(0,40),seller:'Your listing',price:50,item:{name:name.slice(0,40),type:'Material',rarity:'Common',icon:'◇'}});save();toast('Local listing created.');openMarket()}break;
