 case'buy-cosmetic':{let products=[['Moonlit Costume',95],['Starfall Hair',60],['Dawnstag Mount',140],['Wisp Pet',75],['Ember Weapon Effect',80],['Faction Wings',180],['Gem Pouch',0]];let p=products[idx];if(!p)break;if(state.cosmetics.includes(p[0])){toast('You already own this cosmetic.');break}if(state.gems<p[1]){toast('Not enough Gems.');break}state.gems-=p[1];state.cosmetics.push(p[0]);if(idx===2)state.mounted=true;save();refreshHUD();toast(`${p[0]} unlocked!`);openShop()}break;
