 case'enter-dungeon':closeModal();if(state.level<3)toast('The Old Grove is dangerous below level 3—but you may still enter.');actors.push({kind:'monster',type:'wolf',name:'Briar Guardian',x:state.position.x+85,y:state.position.y-20,hp:180,maxHp:180,alive:true,respawn:0,phase:0,boss:true});toast('Briar Guardian awaits nearby.');break;
 case'reset-save':if(!confirm('Return to character creation? Your local save will be erased.'))break;localStorage.removeItem(SAVE_KEY);state=null;closeModal();$('#game').classList.add('hidden');$('#creation').classList.remove('hidden');break;
 case'filter-items':openInventory();break;
 default:break}}
