function setWorldActorTypes(){actors=[];const random=(a,b)=>a+Math.random()*(b-a);for(let i=0;i<8;i++)actors.push({kind:'monster',type:i<6?'slime':'wolf',x:random(250,980),y:random(180,760),hp:i<6?38:65,maxHp:i<6?38:65,alive:true,respawn:0,name:i<6?'Meadow Slime':'Bramble Wolf',phase:random(0,6)});for(const n of [{name:'Mira',role:'Questkeeper',x:475,y:450,color:'#9e7764',mark:'✧'},{name:'Bram',role:'Blacksmith',x:600,y:444,color:'#777e71',mark:'⚒'},{name:'Elowen',role:'Merchant',x:650,y:510,color:'#ad956a',mark:'◇'},{name:'Tomas',role:'Keeper',x:390,y:515,color:'#6e8190',mark:'▣'},{name:'Lysa',role:'Wayfinder',x:723,y:468,color:'#7d9a8b',mark:'⌖'}])actors.push({kind:'npc',...n});}
function startGame(config){state=freshState(config);setWorldActorTypes();$('#creation').classList.add('hidden');$('#game').classList.remove('hidden');$('#hud-name').textContent=state.name;$('#avatar-initial').textContent=state.name[0].toUpperCase();$('#hero-avatar').textContent=state.name[0].toUpperCase();$('#level-label').textContent=`LV. ${state.level} · ${state.className.toUpperCase()}`;$('#skill-name').textContent=classes[state.className].skill.toUpperCase();$('#skill-glyph').textContent=classes[state.className].glyph;camera={x:state.position.x,y:state.position.y};refreshHUD();resizeCanvas();save();toast(`Welcome to Dawnshire, ${state.name}.`);}
