function talkTo(name){switch(name){case'Mira':openQuests();if(!state.quests.some(q=>q.active&&!q.done)){let q=state.quests.find(q=>!q.done);if(q){q.active=true;toast(`New quest: ${q.title}`);refreshHUD();save()}}break;case'Bram':openCraft();break;case'Elowen':openShop();break;case'Tomas':openInventory();break;case'Lysa':openWorld();break;default:toast(`${name} has nothing to say.`)}}
function panelAction(action,value){if(!state)return;const idx=Number(value);switch(action){
 case'select-item':showItemDetail(state.inventory[idx]);break;
 case'equip-item':if(!selectedItem||!slots.includes(selectedItem.type)){toast('This item cannot be equipped.');break}state.equipment[selectedItem.type]=selectedItem.name;selectedItem.equipped=true;toast(`${selectedItem.name} equipped.`);save();openEquipment();break;
 case'use-item':if(!selectedItem)break;if(/potion/i.test(selectedItem.name)||selectedItem.type==='Consumable'){if(state.potions<1){toast('No potions remain.');break}state.potions--;selectedItem.qty=Math.max(0,(selectedItem.qty||1)-1);if(selectedItem.qty===0)state.inventory.splice(state.inventory.indexOf(selectedItem),1);let c=classes[state.className];state.hp=Math.min(c.hp,state.hp+Math.round(c.hp*.45));state.mp=Math.min(c.mp,state.mp+Math.round(c.mp*.3));refreshHUD();save();toast('Potion used · HP and MP restored.');selectedItem=null;openInventory()}else toast('That item cannot be used right now.');break;
