node --input-type=module <<'EOF'
import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync('/home/runner/.local/share/omgithub-playwright/linux.json', 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync('/home/runner/work/_temp/omgithub-runtime/display', 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions });
try {
  const page = await browser.newPage({ viewport: { width: 1024, height: 768 } });
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.goto('http://127.0.0.1:3000', { waitUntil: 'load' });
  await page.locator('#hero-name').fill('Lyra');
  await page.locator('[data-faction="Demons"]').click();
  await page.locator('[data-class="Mage"]').click();
  await page.locator('#begin-btn').click();
  await page.locator('#hud-name').getByText('Lyra').waitFor();
  await page.locator('#mount-btn').click();
  const before = await page.evaluate(() => JSON.parse(localStorage.getItem('aetheria-local-v1')).data);
  await page.reload({ waitUntil: 'load' });
  await page.locator('#hud-name').getByText('Lyra').waitFor();
  const after = await page.evaluate(() => JSON.parse(localStorage.getItem('aetheria-local-v1')).data);
  const result = {
    resumedIntoGame: await page.locator('#game').isVisible(),
    creationHidden: !(await page.locator('#creation').isVisible()),
    character: `${after.name} · ${after.className} · ${after.faction}`,
    savedMountBeforeReload: before.mounted,
    restoredMountAfterReload: after.mounted,
    savedPosition: after.position,
    pageErrors: errors,
  };
  console.log(JSON.stringify(result, null, 2));
  if (!result.resumedIntoGame || !result.creationHidden || !result.restoredMountAfterReload || errors.length) process.exitCode = 1;
  await page.close();
} finally { await browser.close(); }
EOF

